<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">              name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;if&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 指令名称为 if，不带有前缀 v-</span></span>
